pub fn collapseDots(self: *@This(), idx: u32, dir_path: *[:0]u8, path_buf: *bun.PathBuffer, encountered_dot_dot: *bool) Maybe(u32) {
            var component_idx = idx;
            _ = &component_idx;
            var len = dir_path.len;
            _ = &len;
            while ((component_idx < self.patternComponents.items.len)) {
                switch (self.patternComponents.items[@as(usize, @intCast(component_idx))].syntax_hint) {
.Dot => {
if (((len + 2) >= bun.MAX_PATH_BYTES)) {
                    component_idx = (component_idx + 1);
                    return .{ .err = self.handleSysErrWithPath(Syscall.Error.fromCode(.NAMETOOLONG, .open), path_buf[0..len :0]) };
                }
                if ((len == 0)) {
                    path_buf[cp_cast_int(usize, len)] = 46;
                    path_buf[cp_cast_int(usize, (len + 1))] = 0;
                    len = (len + 1);
                } else {
                    path_buf[cp_cast_int(usize, len)] = 47;
                    path_buf[cp_cast_int(usize, (len + 1))] = 46;
                    path_buf[cp_cast_int(usize, (len + 2))] = 0;
                    len = (len + 2);
                }
                component_idx = (component_idx + 1);
},
.DotBack => {
encountered_dot_dot.* = true;
                if (((len + 3) >= bun.MAX_PATH_BYTES)) {
                    component_idx = (component_idx + 1);
                    return .{ .err = self.handleSysErrWithPath(Syscall.Error.fromCode(.NAMETOOLONG, .open), path_buf[0..len :0]) };
                }
                if ((len == 0)) {
                    path_buf[cp_cast_int(usize, len)] = 46;
                    path_buf[cp_cast_int(usize, (len + 1))] = 46;
                    path_buf[cp_cast_int(usize, (len + 2))] = 0;
                    len = (len + 2);
                } else {
                    path_buf[cp_cast_int(usize, len)] = 47;
                    path_buf[cp_cast_int(usize, (len + 1))] = 46;
                    path_buf[cp_cast_int(usize, (len + 2))] = 46;
                    path_buf[cp_cast_int(usize, (len + 3))] = 0;
                    len = (len + 3);
                }
                component_idx = (component_idx + 1);
},
else => {
break;
},
}
