pub fn matchPatternDir(self: *@This(), pattern: *Component, next_pattern: ?*Component, entry_name: []const u8, component_idx: u32, is_last: bool, add: *bool) ?u32 {
            if (((!self.dot) and @This().startsWithDot(entry_name))) {
                return null;
            }
            if (is_ignored(entry_name)) {
                return null;
            }
            if ((pattern.syntax_hint == .Double)) {
                if (((!is_last) and self.matchPatternImpl(next_pattern.?, entry_name))) {
                    if (((component_idx + 1) == (self.patternComponents.items.len - 1))) {
                        add.* = true;
                        return 0;
                    }
                    return 2;
                }
                if (is_last) {
                    add.* = true;
                }
                return 0;
            }
            const matches = self.matchPatternImpl(pattern, entry_name);
            if (matches) {
                if (is_last) {
                    add.* = true;
                    return null;
                }
                return 1;
            }
            return null;
    }

pub fn matchPatternFile(self: *@This(), entry_name: []const u8, component_idx: u32, is_last: bool, pattern: *Component, next_pattern: ?*Component) bool {
