            }
            return self.matchPatternImpl(pattern, entry_name);
    }

pub fn matchPatternImpl(self: *@This(), pattern_component: *Component, filepath: []const u8) bool {
            _ = log("matchPatternImpl: {s}", .{ filepath });
            if (((!self.dot) and @This().startsWithDot(filepath))) {
