            }
            return (switch (pattern_component.syntax_hint) {
.Double, .Single => true,
.WildcardFilepath => matchWildcardFilepath(pattern_component.patternSlice(self.pattern), filepath),
.Literal => matchWildcardLiteral(pattern_component.patternSlice(self.pattern), filepath),
else => self.matchPatternSlow(pattern_component, filepath),
